import{_ as o,o as t,c,a5 as a}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"定义新注解","description":"","frontmatter":{"title":"定义新注解","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/Spring MVC自定义参数解析器/定义新注解.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/Spring MVC自定义参数解析器/定义新注解.md"}'),d={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/Spring MVC自定义参数解析器/定义新注解.md"};function n(i,e,r,p,s,l){return t(),c("div",null,[...e[0]||(e[0]=[a("<div><p>package cn.iocoder.yudao.framework.common.resolver; import java.lang.annotation.*; // 指定该注解应用于方法参数 @Target(ElementType.PARAMETER) // 指定何时应丢弃注解 @Retention(RetentionPolicy.RUNTIME) // 指定该注解应被 javadoc 以及类似工具文档化 @Documented // 自定义注解的定义 public @interface FetchFormSettingArgumentRequestParam { }</p><p>在 Java 中，<code>@</code> 符号用于指定一个接口为注解 (Annotation)。注解是一种特殊的接口，它们提供了一种元数据编程的方法，允许开发者在代码中添加元数据信息。这些信息可以被编译器用来产生警告、编译时和部署时的处理，以及运行时的处理。</p><p>下面是对代码中每个元素的解释：</p><ul><li><p><code>@interface</code>：这个声明指定了一个新的注解类型。注意这里是 <code>@interface</code> 而不是 <code>interface</code>。<code>@interface</code> 用于声明一个注解接口，而 <code>interface</code> 用于声明一个普通接口。 - <code>@Target(ElementType.PARAMETER)</code>：<code>@Target</code> 注解指定了你的注解可以应用于什么样的 Java 元素。在这个例子中，它限制了你的注解只能应用于方法的参数。</p></li><li><p><code>@Retention(RetentionPolicy.RUNTIME)</code>：<code>@Retention</code> 注解指定了你的注解在哪个级别可用。在源代码中(<code>SOURCE</code>)、类文件中(<code>CLASS</code>)或者运行时(<code>RUNTIME</code>)。在这个例子中，它指定了注解是在运行时可用的。</p></li><li><p><code>@Documented</code>：<code>@Documented</code> 注解指定了你的注解会被 javadoc 工具记录，即它会出现在 Java 文档中。</p></li></ul><p>总的来说，<code>@</code> 符号在 <code>@interface</code> 声明中用于指定一个新的注解类型，并通过上述的元注解（如 <code>@Target</code>、<code>@Retention</code> 和 <code>@Documented</code>）来配置注解的行为。</p></div>",1)])])}const g=o(d,[["render",n]]);export{m as __pageData,g as default};
